insert into public.quest_templates (id, family_id, version, category, intensity, title, content, published, variant_key) values
('activity_date_photo_duet_alpha_chill_v2', 'activity_date_photo_duet', 2, 'date_night', 'chill', 'Two Views, One Story: something that looks like a first date', '{"id":"activity_date_photo_duet_alpha_chill_v2","familyId":"activity_date_photo_duet","variantKey":"alpha","version":2,"category":"date_night","intensity":"chill","title":"Two Views, One Story: something that looks like a first date","hook":"Same brief. Two different photos. Don''t show each other until the reveal. Brief: something that looks like a first date.","durationMinutes":25,"minParticipants":2,"maxParticipants":8,"cost":{"minMinor":0,"maxMinor":0,"currency":"USD","scope":"total","venueCostUnknown":false,"note":"Use things you already own and a free, permitted place. No purchase or booking is required. Any confirmed travel or entry charges still count toward your budget."},"settings":["home","outside","venue"],"interests":["making","mystery_date"],"roles":["main_character","mastermind","camera_person","rotate"],"preparation":"start_now","conflicts":[],"venuePermissionRequired":false,"arrangementRequired":false,"adultOnly":false,"supportsAdultContext":false,"requiresVolunteer":false,"beats":[{"label":"Set up the challenge","action":"Read the photo brief together. Agree a small area and keep your screens hidden from each other. Today''s brief: something that looks like a first date. Take one photo each and compare them.","filming":"Film both of you naming the photo brief with your screens turned away. Keep the finished photos hidden.","caption":"Two Views, One Story"},{"label":"Do the activity","action":"Each partner makes a photo answering the same brief, without seeing the other''s frame. Compare your choices and combine them into one two-image story. Take one photo each and compare them.","filming":"Record a few seconds of each person choosing a subject or framing a shot; avoid revealing the finished images.","caption":"The attempt"},{"label":"Show the result","action":"Reveal both photos at the s